  }
};
var eui = String(msg.deveui || '').toUpperCase();
var device = devices[eui];
var data = msg.payload;

// Temporary read-only diagnostics around the existing monitoring writes.
function acCounterDebug(stage, extra) {
  var message = {
    diagnostic: stage, node_id: node.id || null, device_eui: eui || null,
    flow_id: typeof env !== 'undefined' ? env.get('NR_FLOW_ID') || null : null
  };
  Object.keys(extra || {}).forEach(function (key) { message[key] = extra[key]; });
  node.warn(JSON.stringify(message));
}
var debugWs523 = (device && device.model === 'WS523') || msg.deviceType === 'WS523';
if (debugWs523) {
  var obj = data && typeof data === 'object' ? data : {};
  acCounterDebug('ac_counter_input', {
    device_known: !!device, payload_type: typeof data, payload_fields: Object.keys(obj),
    counter_present: Object.prototype.hasOwnProperty.call(obj, 'power_consumption'),
    counter_wh: obj.power_consumption === undefined ? null : obj.power_consumption,
    counter_type: typeof obj.power_consumption,
    power_w: obj.active_power === undefined ? null : obj.active_power
  });
}
if (!device || !data || typeof data !== 'object') return null;
var cache = flow.get('telemetry_latest_v1') || {};
var saved = cache[eui] || {};
var now = Date.now(), acEnergyUpdated = false;
function save(key, value) { saved[key] = { value: value, receivedAt: now }; }
function number(key, value, min, max) {
  if (typeof value === 'number' && Number.isFinite(value) && value >= min && value <= max) save(key, value);
}
if (device.model === 'WS523' || device.model === 'WS502') {
  number('power_w', data.active_power, 0, 4294967295);
  number('energy_wh', data.power_consumption, 0, 4294967295);
  // Keep genuine counter observations for the latest 10-minute AC reports.
  // Publishing the cache never adds a point or renews its observation time.
  if (device.model === 'WS523' && device.room !== 'ATAS_PINTU' && typeof data.power_consumption === 'number' && Number.isFinite(data.power_consumption) && data.power_consumption >= 0 && data.power_consumption <= 4294967295) {
    var points = Array.isArray(saved.energy_minute_points) ? saved.energy_minute_points : [];
    points = points.filter(function (p) { return p && Number.isFinite(p.at) && p.at < now && now - p.at <= 2700000 && Number.isFinite(p.wh); });
    points.push({ at: now, wh: data.power_consumption });
    saved.energy_minute_points = points.slice(-16);
    acEnergyUpdated = true;
  }
} else {
  number('temperature_c', data.temperature, -100, 150);
  number('humidity_pct', data.humidity, 0, 100);
  // Monitoring website uses only the current region_1 sensor status.
  // Clear values produced by the old people-count/combined-region rule once.
  if (saved.occupancy_source !== 'region_1') { delete saved.occupancy; saved.occupancy_source = 'region_1'; }
  if (Object.prototype.hasOwnProperty.call(data, 'region_1')) {
    if (data.region_1 === 'occupied' || data.region_1 === 'vacant') save('occupancy', data.region_1);
    else delete saved.occupancy;
  }
  // Only an explicit light report can update its value and observation time.
  if (Object.prototype.hasOwnProperty.call(data, 'illuminance_status') || Object.prototype.hasOwnProperty.call(data, 'illumination')) {
    var light = Object.prototype.hasOwnProperty.call(data, 'illuminance_status') ? data.illuminance_status : data.illumination;
    if (light === 'bright' || light === 'dim') save('illumination', light);
    else delete saved.illumination;
  }
}
// History-only atau battery-only tidak memperbarui umur nilai sebelumnya.
cache[eui] = saved;
flow.set('telemetry_latest_v1', cache);
if (debugWs523) {
  var readBack = flow.get('telemetry_latest_v1') || {}, readRecord = readBack[eui] || {};
  var entry = readRecord.energy_wh || {};
  var samples = Array.isArray(readRecord.energy_minute_points) ? readRecord.energy_minute_points : [];
  var last = samples[samples.length - 1], previous = samples[samples.length - 2];
  acCounterDebug('ac_counter_saved', {
    cache_device_count: Object.keys(readBack).length,
    record_exists: Object.prototype.hasOwnProperty.call(readBack, eui),
    record_fields: Object.keys(readRecord),
    stored_counter_wh: entry.value === undefined ? null : entry.value,
    stored_counter_at_utc: typeof entry.receivedAt === 'number' ? new Date(entry.receivedAt).toISOString() : null,
    history_count: samples.length,
    gap_seconds: last && previous ? (last.at - previous.at) / 1000 : null,
    delta_wh: last && previous ? last.wh - previous.wh : null,
    new_counter_sample: !!acEnergyUpdated
  });
}

return acEnergyUpdated ? { topic: 'ac_energy_updated' } : null;

// Ubah 15 menjadi 10 jika ingin interval 10 menit.
var intervalMinutes = 10;
var powerMaxAgeMinutes = 30;
var environmentMaxAgeMinutes = 30;
var occupancyMaxAgeMinutes = 15;
var devices = {
  "24E124148060C6A0": {
    "model": "WS523",
