    "name": "WS502_RUANG_MAGANG"
  },
  "24E1247710638799": {
    "model": "WS502",
    "room": "BU_DINI",
    "name": "WS502_BU_DINI"
  }
};
var now = Date.now();
var slot = Math.floor(now / (intervalMinutes * 60000));
if (msg.topic !== 'sample_now') {
    if (context.get('lastSlot') === slot) return null;
    context.set('lastSlot', slot);
}
var cache = flow.get('telemetry_latest_v1') || {};
var fields = ['power_w', 'energy_wh', 'temperature_c', 'humidity_pct', 'occupancy', 'illumination'];
var records = Object.keys(devices).map(function(eui) {
    var device = devices[eui];
    var saved = cache[eui] || {};
    var row = { device_eui: eui, device_name: device.name, model: device.model, room: device.room };
    var isMeter = device.model === 'WS523' || device.model === 'WS502';
    var required = isMeter ? ['power_w', 'energy_wh'] : ['temperature_c', 'humidity_pct', 'occupancy', 'illumination'];
    var fresh = 0, seen = 0;
    fields.forEach(function(key) {
        var entry = saved[key];
        var applicable = required.indexOf(key) !== -1;
        var ageMinutes = key === 'occupancy' ? occupancyMaxAgeMinutes : isMeter ? powerMaxAgeMinutes : environmentMaxAgeMinutes;
        var valid = applicable && entry && entry.receivedAt <= now && now - entry.receivedAt <= ageMinutes * 60000;
        row[key] = valid ? entry.value : null;
        row[key + '_at'] = applicable && entry ? new Date(entry.receivedAt).toISOString() : null;
        if (applicable && entry) seen++;
        if (valid) fresh++;
    });
    row.quality = !seen ? 'missing' : !fresh ? 'stale' : fresh === required.length ? 'fresh' : 'partial';
    return row;
});
var id = 'ug65-ussc-' + (msg.topic === 'sample_now' ? 'manual-' + now + '-' + Math.random().toString(36).slice(2, 8) : intervalMinutes + 'm-' + slot);
return { telemetryAction: 'enqueue', payload: { type: 'telemetry_snapshot', version: 2, source: 'ug65-ussc', id: id,
    sampled_at: new Date(now).toISOString(), interval_minutes: intervalMinutes, records: records } };

