// Read the existing power and observed energy-counter cache only. No SQL or control commands.
var now = Date.now(), cache = flow.get('telemetry_latest_v1') || {};
var meters = ["24E124148060C6A0", "24E12414806031FC", "24E124148060D73E", "24E1241480609B86", "24E1247710630110", "24E124771063F466", "24E1247710633F88", "24E1247710638799"];
var records = meters.map(function (eui) {
    var entry = (cache[eui] || {}).power_w;
    // Retain each last actual value; backend marks old observations as previous.
    var valid = entry && typeof entry.value === 'number' && Number.isFinite(entry.value) && entry.value >= 0 && entry.value <= 4294967295 && Number.isFinite(entry.receivedAt) && entry.receivedAt <= now;
    var energy = (cache[eui] || {}).energy_minute_points;
    var points = Array.isArray(energy) ? energy.filter(function (p) { return p && Number.isFinite(p.at) && p.at <= now && now - p.at <= 2700000 && Number.isFinite(p.wh) && p.wh >= 0 && p.wh <= 4294967295; }).slice(-16).map(function (p) { return { at: new Date(p.at).toISOString(), wh: p.wh }; }) : [];
    return { device_eui: eui, power_w: valid ? entry.value : null, power_w_at: entry && Number.isFinite(entry.receivedAt) && Number.isFinite(new Date(entry.receivedAt).getTime()) ? new Date(entry.receivedAt).toISOString() : null, energy_points: points };
});
return { topic: 'office1/monitoring/power', qos: '0', retain: true, payload: JSON.stringify({ type: 'office_power', version: 1, source_id: 'ug65-ussc', sampled_at_utc: new Date(now).toISOString(), interval_minutes: 1, records: records }) };

// READ ONLY: no context writes, MQTT, downlink, SQL, keys, or control.
var location='UG65',packetAt=null;
var cache=flow.get('telemetry_latest_v1')||{};
function lookup(eui){var r=cache[eui]||{},v=r.energy_wh||{};return {wh:v.value===undefined?null:v.value,at:v.receivedAt,points:Array.isArray(r.energy_minute_points)?r.energy_minute_points:[]};}
var now=Date.now();
var meters=['24E124148060C6A0','24E12414806031FC','24E124148060D73E','24E1241480609B86'];
function iso(t){return typeof t==='number'&&Number.isFinite(t)?new Date(t).toISOString():null;}
var records=meters.map(function(eui){
    var r=lookup(eui),points=r.points||[];
    var clean=points.filter(function(p){return p&&Number.isFinite(p.at)&&Number.isFinite(p.wh);}).slice().sort(function(a,b){return a.at-b.at;});
    var end=clean[clean.length-1],start=clean[clean.length-2];
    var gap=start&&end?(end.at-start.at)/1000:null;
    var age=end?(now-end.at)/1000:null,delta=start&&end?end.wh-start.wh:null;
    var reason=!points.length?'history_empty':clean.length<2?'need_two_reports':gap<510?'reports_less_than_8m30s':gap>690?'reports_more_than_11m30s':delta<0?'counter_reset':age<0?'future_time':age>900?'last_counter_older_than_15m':'pair_looks_valid';
    return {device_eui:eui,counter_wh:r.wh,counter_at_utc:iso(r.at),history_count:points.length,valid_points:clean.length,gap_seconds:gap,delta_wh:delta,last_age_seconds:age,reason:reason,last_points:clean.slice(-6).map(function(p){return {at_utc:iso(p.at),wh:p.wh};})};
});
msg.payload={diagnostic:'ac_counter_readonly',location:location,checked_at_utc:iso(now),packet_at_utc:packetAt||null,records:records};
return msg;
